content.arguments:
{"command":"$ws = "E:\Workspace\naumi-file-delivery-single-path\runtime\file-delivery-single-path-af9ed630-b14a-412b-ad62-0ed6770920d3\home\naumi\workspaces\bot-32f377fa-f6b3-4e36-95a7-7c66bf512840"
Get-ChildItem $ws | Select-Object Name,Length,LastWriteTime | Format-Table -AutoSize
$csvPath = Join-Path $ws "汇总.csv"
Write-Output "=== 汇总.csv raw ==="
Get-Content $csvPath -Encoding UTF8
Write-Output "=== independent recompute vs 汇总.csv ==="
$src = Import-Csv (Join-Path $ws "sales.csv")
$out = Import-Csv $csvPath
foreach ($r in $out) {
  if ($r.channel -eq 'total') {
    $eo = ($src | Measure-Object -Property {[int]$_.orders} -Sum).Sum
    $ea = ($src | Measure-Object -Property {[int]$_.amount} -Sum).Sum
  } else {
    $g = $src | Where-Object { $_.channel -eq $r.channel }
    $eo = ($g | Measure-Object -Property {[int]$_.orders} -Sum).Sum
    $ea = ($g | Measure-Object -Property {[int]$_.amount} -Sum).Sum
  }
  $ok = ([int]$r.orders -eq $eo) -and ([int]$r.amount -eq $ea)
  Write-Output ("{0,-8} csv=({1},{2}) recomputed=({3},{4}) MATCH={5}" -f $r.channel,$r.orders,$r.amount,$eo,$ea,$ok)
}
Write-Output ("Header=" + ((Get-Content $csvPath -Encoding UTF8 -TotalCount 1)))
Write-Output ("MdBytes=" + (Get-Item (Join-Path $ws "日报.md")).Length)","description":"Verify delivered files and recompute CSV totals"}
